package com.novacommerce.order.config; import org.springframework.security.oauth2.core.*; import org.springframework.security.oauth2.jwt.Jwt; public class AudienceValidator implements OAuth2TokenValidator<Jwt>{private final String audience;public AudienceValidator(String a){audience=a;}public OAuth2TokenValidatorResult validate(Jwt j){return j.getAudience().contains(audience)?OAuth2TokenValidatorResult.success():OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token","Audience missing",null));}}
